    private boolean persistMissionOutcome(int houseIndex, MissionProgression.Decision decision) {
        if (houseIndex < 0 || houseIndex > 2 || decision == null || !decision.terminal) {
            return false;
        }
        SharedPreferences prefs = getSharedPreferences(PROGRESS_PREFS, 0);
        SharedPreferences.Editor editor = prefs.edit();
        if (decision.won) {
            int old = unlockedLevelForHouse(houseIndex);
            if (decision.unlockedLevel > old) {
                editor.putInt("max_level_" + houseIndex, decision.unlockedLevel);
            }
            if (decision.campaignComplete) {
                editor.putBoolean("campaign_complete_" + houseIndex, true);
            }
            editor.putLong("continue_cutoff_after_win", System.currentTimeMillis());
        }
        return editor.commit();
    }

