        private void cancelWorldMouseGesture() {
            removeCallbacks(this.mouseFavoriteLongPressRunnable);
            this.mouseLongPressFavorite = null;
            this.mouseWorldButton = 0;
            this.mouseMarquee.cancel();
            this.multiSelectionGesture = false;
            this.multiSelectionBounds.setEmpty();
            invalidate();
        }

        private void mouseRightClickWithStructureSelected(float sx, float sy) {
            int originalRaw;
            if (MainActivity.this.nativeHandle != 0 && (originalRaw = selectedStructureRaw()) >= 0) {
                int selectedType = MainActivity.this.tacticalAux != null ? (MainActivity.this.tacticalAux[3] >>> 16) & 255 : -1;
                int phase = selectedConstructionPhase();
                int packed = packedAtScreen(sx, sy);
                if (selectedType == 8 && phase == 2) {
                    MainActivity.nativeTacticalClearSelection(MainActivity.this.nativeHandle);
                    clearConstructionPreview();
                    this.constructionFeedback = "PLACE LATER";
                    MainActivity.this.diagnosticLog("MOUSE_BUILD", "PLACE_LATER");
                } else if (selectedType == 8 && phase == 1) {
                    int stopped = MainActivity.nativeStructureStop(MainActivity.this.nativeHandle);
                    if (stopped < 0) {
                        MainActivity.this.handleCoreFailure("STRUCTURE_STOP_INVARIANT_FAILED");
                    }
                    this.constructionFeedback = stopped > 0 ? "STOPPED" : "NOTHING TO STOP";
                    MainActivity.this.diagnosticLog("MOUSE_BUILD", "STOP=" + stopped);
                } else {
                    FavoriteRef target = favoriteObjectAtScreen(sx, sy);
                    if (target != null && target.kind == 2 && target.raw == originalRaw) {
                        boolean fixing = (selectedStructureControlAux() & 4096) != 0;
                        if (selectedStructureCanFix() || fixing) {
                            int repaired = MainActivity.nativeStructureFix(MainActivity.this.nativeHandle);
                            if (repaired < 0) {
                                MainActivity.this.handleCoreFailure("STRUCTURE_FIX_INVARIANT_FAILED");
                            } else if (repaired > 0 && MainActivity.this.achievementMissionState.active) {
                                MainActivity.this.achievementMissionState.repairUsed = SMOOTH_HUD_PURCHASE_SCROLL;
                            }
                            this.constructionFeedback = repaired > 0 ? "FIX STARTED" : "FIX UNAVAILABLE";
                            MainActivity.this.diagnosticLog("MOUSE_STRUCTURE", "FIX=" + repaired);
                        }
                        refreshInteractionSnapshots();
                        invalidate();
                        return;
                    }
                }
                if (packed >= 0) {
                    this.inspectedMapPacked = packed;
                    MainActivity.nativeTacticalSelectPacked(MainActivity.this.nativeHandle, packed);
                }
                refreshInteractionSnapshots();
                MainActivity.this.consumeSoundEventSnapshot();
                invalidate();
            }
        }

        @Override // android.view.View
        public boolean onGenericMotionEvent(MotionEvent e) {
            if ((e.getSource() & 8194) == 8194 && (e.getActionMasked() == 7 || e.getActionMasked() == 9)) {
                MainActivity.this.keepMouseImmersiveUi();
                rememberWorldMousePosition(e);
                return SMOOTH_HUD_PURCHASE_SCROLL;
            }
            if ((e.getSource() & 8194) == 8194 && e.getActionMasked() == 8) {
                rememberWorldMousePosition(e);
                float ticks = e.getAxisValue(9);
                if (ticks == 0.0f) {
                    return SMOOTH_HUD_PURCHASE_SCROLL;
                }
                if (this.debugPanelOpen && this.debugPanelRect.contains(e.getX(), e.getY())) {
                    float u = menuUiScale();
                    if (this.menuScreen == 2) {
                        this.menuSettingsScrollOffset = Math.max(0.0f, Math.min(settingsScrollMax(u), this.menuSettingsScrollOffset - ((MainActivity.CONSTRUCTION_PREVIEW_SMOOTHING_PER_SECOND * ticks) * u)));
                    } else if (this.menuScreen == 1) {
                        this.menuLoadScrollOffset = Math.max(0.0f, Math.min(loadScrollMax(u), this.menuLoadScrollOffset - ((MainActivity.CONSTRUCTION_PREVIEW_SMOOTHING_PER_SECOND * ticks) * u)));
                    } else if (this.menuScreen == 6) {
                        this.menuAchievementsScrollOffset = Math.max(0.0f, Math.min(achievementsScrollMax(u), this.menuAchievementsScrollOffset - ((MainActivity.CONSTRUCTION_PREVIEW_SMOOTHING_PER_SECOND * ticks) * u)));
                    }
                    invalidate();
                    return SMOOTH_HUD_PURCHASE_SCROLL;
                }
                if (!this.debugPanelOpen && this.tacticalHudRect.contains(e.getX(), e.getY())) {
                    int max = hudMenuMaxOffset(currentHudMenuChoiceCount());
                    this.hudMenuOffset = Math.max(0, Math.min(max, this.hudMenuOffset - (((int) Math.signum(ticks)) * hudMenuColumns())));
                    this.hudMenuVisualItems = this.hudMenuOffset;
                    this.hudMenuScrollAnimating = false;
                    updateMousePurchaseHover(hudMenuChoiceAtMouseHover(e.getX(), e.getY()));
                    invalidate();
                    return SMOOTH_HUD_PURCHASE_SCROLL;
                }
            }
            return super.onGenericMotionEvent(e);
        }

