        private List<Integer> escortComponentOrder(int seed, int[] parent) {
            boolean z;
            List<Integer> empty = new ArrayList<>();
            if (seed < 0 || seed >= 128 || parent == null || parent.length < 128 || !connectedPlayerUnitLive(seed)) {
                return empty;
            }
            int i = parent[seed];
            boolean z2 = SMOOTH_HUD_PURCHASE_SCROLL;
            boolean hasRelation = i >= 0;
            if (!hasRelation) {
                int raw = 0;
                while (true) {
                    if (raw >= 128) {
                        break;
                    }
                    if (parent[raw] == seed) {
                        hasRelation = SMOOTH_HUD_PURCHASE_SCROLL;
                        break;
                    }
                    raw++;
                }
            }
            if (!hasRelation) {
                return empty;
            }
            boolean[] component = new boolean[128];
            ArrayDeque<Integer> queue = new ArrayDeque<>();
            component[seed] = SMOOTH_HUD_PURCHASE_SCROLL;
            queue.add(Integer.valueOf(seed));
            int componentCount = 1;
            while (!queue.isEmpty()) {
                int raw2 = queue.removeFirst().intValue();
                int p = parent[raw2];
                if (p >= 0 && !component[p]) {
                    component[p] = SMOOTH_HUD_PURCHASE_SCROLL;
                    componentCount++;
                    queue.addLast(Integer.valueOf(p));
                }
                for (int child = 0; child < 128; child++) {
                    if (parent[child] == raw2 && !component[child]) {
                        component[child] = SMOOTH_HUD_PURCHASE_SCROLL;
                        componentCount++;
                        queue.addLast(Integer.valueOf(child));
                    }
                }
            }
            if (componentCount <= 1) {
                return empty;
            }
            int root = seed;
            boolean[] parentWalk = new boolean[128];
            boolean cycle = false;
            while (parent[root] >= 0 && component[parent[root]]) {
                if (parentWalk[root] || parentWalk[parent[root]]) {
                    cycle = SMOOTH_HUD_PURCHASE_SCROLL;
                    break;
                }
                parentWalk[root] = SMOOTH_HUD_PURCHASE_SCROLL;
                root = parent[root];
            }
            if (cycle) {
                int raw3 = 0;
                while (true) {
                    if (raw3 >= 128) {
                        break;
                    }
                    if (component[raw3]) {
                        root = raw3;
                        break;
                    }
                    raw3++;
                }
            }
            List<Integer> order = new ArrayList<>(componentCount);
            boolean[] emitted = new boolean[128];
            queue.clear();
            queue.add(Integer.valueOf(root));
            emitted[root] = SMOOTH_HUD_PURCHASE_SCROLL;
            while (!queue.isEmpty()) {
                int raw4 = queue.removeFirst().intValue();
                order.add(Integer.valueOf(raw4));
                int child2 = 0;
                while (child2 < 128) {
                    if (!component[child2] || emitted[child2]) {
                        z = z2;
                    } else {
                        z = z2;
                        if (parent[child2] == raw4) {
                            emitted[child2] = z;
                            queue.addLast(Integer.valueOf(child2));
                        }
                    }
                    child2++;
                    z2 = z;
                }
            }
            for (int raw5 = 0; raw5 < 128; raw5++) {
                if (component[raw5] && !emitted[raw5]) {
                    order.add(Integer.valueOf(raw5));
                }
            }
            return order;
        }

