        private void cancelFavoriteCameraMotion() {
            this.favoriteCameraTargetX = Float.NaN;
            this.favoriteCameraTargetY = Float.NaN;
            this.favoriteCameraMotionNanos = 0L;
            this.favoriteCameraFollowUnit = null;
        }

        private void clampFavoriteCameraTarget() {
            float maxX = Math.max(0.0f, (this.currentMapW * 32) - this.currentActiveViewportLogicalW);
            float maxY = Math.max(0.0f, (this.currentMapH * 32) - this.currentViewportLogicalH);
            this.favoriteCameraTargetX = Math.max(0.0f, Math.min(maxX, this.favoriteCameraTargetX));
            this.favoriteCameraTargetY = Math.max(0.0f, Math.min(maxY, this.favoriteCameraTargetY));
        }

        private void setFavoriteCameraTargetForWorld(float worldX, float worldY) {
            if (MainActivity.this.renderWords == null) {
                return;
            }
            int bounds = MainActivity.this.renderWords[4];
            int minX = bounds & 255;
            int minY = (bounds >>> 8) & 255;
            this.favoriteCameraTargetX = ((worldX - minX) * MainActivity.TACTICAL_CURSOR_SPEED_CELLS_PER_SECOND) - (this.currentActiveViewportLogicalW * 0.5f);
            this.favoriteCameraTargetY = ((worldY - minY) * MainActivity.TACTICAL_CURSOR_SPEED_CELLS_PER_SECOND) - (this.currentViewportLogicalH * 0.5f);
            clampFavoriteCameraTarget();
        }

        private void beginFavoriteCameraMotion(float worldX, float worldY, FavoriteRef followUnit) {
            setFavoriteCameraTargetForWorld(worldX, worldY);
            this.favoriteCameraFollowUnit = followUnit;
            this.favoriteCameraMotionNanos = this.currentFrameNanos != 0 ? this.currentFrameNanos : System.nanoTime();
            this.cameraInitialized = SMOOTH_HUD_PURCHASE_SCROLL;
        }

        private boolean favoriteUnitStillAssigned(FavoriteRef ref) {
            if (ref == null || ref.kind != 1 || customFavoriteIndex(ref) < 0) {
                return false;
            }
            return SMOOTH_HUD_PURCHASE_SCROLL;
        }

        private float favoriteCameraSpeedForDistance(float distancePixels) {
            float distanceCells = distancePixels / MainActivity.TACTICAL_CURSOR_SPEED_CELLS_PER_SECOND;
            if (distanceCells <= 8.0f) {
                return MainActivity.FAVORITE_CAMERA_SPEED_CELLS_PER_SECOND;
            }
            float extra = (distanceCells - 8.0f) * 6.0f;
            return Math.min(MainActivity.FAVORITE_CAMERA_FAST_MAX_CELLS_PER_SECOND, MainActivity.FAVORITE_CAMERA_SPEED_CELLS_PER_SECOND + extra);
        }

        private void advanceFavoriteCameraMotion(long now) {
            if (!this.cameraInitialized || MainActivity.this.renderWords == null) {
                return;
            }
            if (this.favoriteCameraFollowUnit != null) {
                FavoriteRef ref = this.favoriteCameraFollowUnit;
                if (!favoriteRefIsLive(ref) || !favoriteUnitStillAssigned(ref) || !favoriteRefIsSelected(ref)) {
                    this.favoriteCameraFollowUnit = null;
                } else {
                    int combat = (MainActivity.this.unitCombatAux == null || ref.raw >= MainActivity.this.unitCombatAux.length) ? 0 : MainActivity.this.unitCombatAux[ref.raw];
                    setFavoriteCameraTargetForWorld(unitRenderWorldX(ref.raw, combat), unitRenderWorldY(ref.raw, combat));
                }
            }
            if (Float.isNaN(this.favoriteCameraTargetX) || Float.isNaN(this.favoriteCameraTargetY)) {
                return;
            }
            if (this.favoriteCameraMotionNanos <= 0 || now <= this.favoriteCameraMotionNanos) {
                this.favoriteCameraMotionNanos = now;
                return;
            }
            float dt = Math.min(0.05f, (now - this.favoriteCameraMotionNanos) / 1.0E9f);
            this.favoriteCameraMotionNanos = now;
            if (dt <= 0.0f) {
                return;
            }
            float dx = this.favoriteCameraTargetX - this.cameraX;
            float dy = this.favoriteCameraTargetY - this.cameraY;
            float distance = (float) Math.sqrt((dx * dx) + (dy * dy));
            if (distance <= 0.01f) {
                this.cameraX = this.favoriteCameraTargetX;
                this.cameraY = this.favoriteCameraTargetY;
                if (this.favoriteCameraFollowUnit == null) {
                    this.favoriteCameraTargetX = Float.NaN;
                    this.favoriteCameraTargetY = Float.NaN;
                    this.favoriteCameraMotionNanos = 0L;
                }
                clampCamera();
                return;
            }
            float step = favoriteCameraSpeedForDistance(distance) * MainActivity.TACTICAL_CURSOR_SPEED_CELLS_PER_SECOND * dt;
            if (step >= distance) {
                this.cameraX = this.favoriteCameraTargetX;
                this.cameraY = this.favoriteCameraTargetY;
            } else {
                float k = step / distance;
                this.cameraX += dx * k;
                this.cameraY += dy * k;
            }
            clampCamera();
        }

