        private boolean handleCheatHideDialogTouch(MotionEvent event) {
            if (event.getActionMasked() == 3) {
                closeCheatHideDialog();
                invalidate();
                return SMOOTH_HUD_PURCHASE_SCROLL;
            }
            if (event.getActionMasked() != 1) {
                return SMOOTH_HUD_PURCHASE_SCROLL;
            }
            if (this.cheatHideDialogIgnoreRelease) {
                this.cheatHideDialogIgnoreRelease = false;
                this.cheatLongPressTriggered = false;
                resetWorldTouchState();
                return SMOOTH_HUD_PURCHASE_SCROLL;
            }
            float x = event.getX();
            float y = event.getY();
            if (this.cheatHideDialogCancelRect.contains(x, y) || !this.cheatHideDialogRect.contains(x, y)) {
                closeCheatHideDialog();
                invalidate();
                return SMOOTH_HUD_PURCHASE_SCROLL;
            }
            if (this.cheatHideDialogActionRect.contains(x, y) && this.cheatHideDialogSlot >= 0) {
                int slot = this.cheatHideDialogSlot;
                closeCheatHideDialog();
                MainActivity.this.setGameplayCheatButtonVisible(slot, false);
                performClick();
                invalidate();
            }
            return SMOOTH_HUD_PURCHASE_SCROLL;
        }

        private void drawGameplayCheatNavigation(Canvas canvas, Layout layout) {
            if (this.suppressOverlayForCapture || this.frontMenuOpen) {
                return;
            }
            if (MainActivity.this.renderWords == null) {
                return;
            }
            for (int i = this.cheatButtonOrder.size() - 1; i >= 0; i--) {
                int slot = this.cheatButtonOrder.get(i).intValue();
                if (!MainActivity.this.gameplayCheatButtonVisible(slot)) {
                    this.cheatButtonOrder.remove(i);
                }
            }
            for (int i2 = 0; i2 < this.cheatButtonRects.length; i2++) {
                this.cheatButtonRects[i2].setEmpty();
                this.cheatButtonSlotForRect[i2] = -1;
            }
            float s = Math.max(1.0f, layout.scale);
            float diameter = MainActivity.CHEAT_BUTTON_DIAMETER_LOGICAL * s;
            float gap = s * 4.0f;
            float margin = 4.0f * s;
            float right = (this.tacticalHudRect.width() > 0.0f ? this.tacticalHudRect.left : this.activeViewportRect.right) - margin;
            float top = this.activeViewportRect.top + margin;
            int drawn = 0;
            for (Integer value : this.cheatButtonOrder) {
                if (value != null && value.intValue() >= 0 && value.intValue() <= 4) {
                    if (MainActivity.this.gameplayCheatButtonVisible(value.intValue())) {
                        if (drawn < this.cheatButtonRects.length) {
                            float r = right - (drawn * (diameter + gap));
                            RectF rect = this.cheatButtonRects[drawn];
                            rect.set(r - diameter, top, r, top + diameter);
                            if (rect.left < this.activeViewportRect.left + margin) {
                                rect.setEmpty();
                                return;
                            } else {
                                this.cheatButtonSlotForRect[drawn] = value.intValue();
                                drawGameplayCheatCircle(canvas, rect, value.intValue(), MainActivity.this.gameplayCheatActive(value.intValue()));
                                drawn++;
                            }
                        } else {
                            return;
                        }
                    }
                }
            }
        }

