            drawConstructionPreview(canvas, minX, minY, mapW, mapH, layout);
            updateStructureIndicatorBlinkPhases();
            drawStructureRepairIndicators(canvas, minX, minY, mapW, mapH, layout);
            drawStructurePowerWarningIndicators(canvas, minX, minY, mapW, mapH, layout);
