        private int palaceRechargeRemaining() {
            if (selectedPlayerPalace()) {
                return (MainActivity.this.palaceAux[2] & 65535) + ((MainActivity.this.palaceAux[2] >>> 16) & 65535);
            }
            return 0;
        }

        private int palaceRechargeElapsed() {
            int total = palaceRechargeTotal();
            if (total <= 0) {
                return 0;
            }
            if (palaceReady()) {
                return total;
            }
            int remaining = Math.max(0, Math.min(total, palaceRechargeRemaining()));
            return Math.max(0, total - remaining);
        }

        private int palaceRechargePercent() {
            int total = palaceRechargeTotal();
            if (total <= 0) {
                return palaceReady() ? 100 : 0;
            }
            return Math.max(0, Math.min(100, (int) Math.round((palaceRechargeElapsed() * 100.0d) / total)));
        }

