        private String selectedUnitOrderLabel() {
            if (selectedUnitRaw() < 0 || MainActivity.this.tacticalAux == null) {
                return "";
            }
            int type = (MainActivity.this.tacticalAux[3] >>> 16) & 255;
            int action = (MainActivity.this.tacticalAux[3] >>> 24) & 255;
            int targetMove = MainActivity.this.tacticalAux[12] & 65535;
            int targetAttack = 65535 & MainActivity.this.tacticalAux[13];
            if (type == 17 && selectedUnitSpecialPending()) {
                return "DEPLOYING";
            }
            if (type == 11 && (selectedUnitSpecialPending() || action == 10)) {
                return "DESTRUCT";
            }
            if (type != 16) {
                if (targetAttack != 0) {
                    return "ATTACK";
                }
                if (targetMove != 0) {
                    return "MOVE";
                }
                if (action == 0) {
                    return "ATTACK";
                }
                return action == 3 ? "GUARD" : action == 4 ? "AREA GUARD" : action == 8 ? "AMBUSH" : action == 11 ? "HUNT" : "";
            }
            int cargo = (MainActivity.this.tacticalAux[14] >>> 16) & 255;
            int state = MainActivity.this.tacticalAux.length > 15 ? MainActivity.this.tacticalAux[15] : 0;
            boolean inside = (state & 512) != 0 ? SMOOTH_HUD_PURCHASE_SCROLL : false;
            boolean manual = (state & RazorTerrainAtlas.HEIGHT) != 0 ? SMOOTH_HUD_PURCHASE_SCROLL : false;
            boolean refineryWait = (state & GenesisObjectArt.VRAM_PATTERN_COUNT) != 0 ? SMOOTH_HUD_PURCHASE_SCROLL : false;
            int movingSpeed = (state >>> 16) & 255;
            if (inside) {
                return cargo > 0 ? "UNLOADING" : "WAITING";
            }
            if (refineryWait) {
                if (targetMove == 0 && movingSpeed == 0) {
                    return "WAITING";
                }
                return "TO REFINERY";
            }
            if (manual) {
                if (targetMove != 0 || movingSpeed != 0) {
                    return "MOVE";
                }
                return "WAITING";
            }
            boolean structureMove = (targetMove & 49152) == 32768 ? SMOOTH_HUD_PURCHASE_SCROLL : false;
            int nextAction = MainActivity.this.tacticalAux.length > 16 ? 255 & MainActivity.this.tacticalAux[16] : 255;
            if (action == 6 || nextAction == 6 || (action == 1 && structureMove)) {
                return "TO REFINERY";
            }
            if (action == 5) {
                if (targetMove == 0 && movingSpeed == 0) {
                    return cargo > 0 ? "HARVESTING" : "SEARCHING";
                }
                return "TO SPICE";
            }
            if (targetMove != 0 || movingSpeed != 0) {
                return "MOVE";
            }
            return "WAITING";
        }

