        private boolean centerCameraOnEncodedObject(int encoded) {
            float worldY;
            float worldX;
            int combat = 0;
            if (MainActivity.this.renderWords == null || encoded == 0) {
                return false;
            }
            int encodedType = (encoded >>> 14) & 3;
            int raw = encoded & 16383;
            if (encodedType == 1) {
                if (raw < 0 || raw >= 128) {
                    return false;
                }
                if ((Integer.MIN_VALUE & MainActivity.this.renderWords[(raw * 4) + MainActivity.UNIT_OFFSET]) == 0) {
                    return false;
                }
                if (MainActivity.this.unitCombatAux != null && raw < MainActivity.this.unitCombatAux.length) {
                    combat = MainActivity.this.unitCombatAux[raw];
                }
                worldX = unitRenderWorldX(raw, combat);
                worldY = unitRenderWorldY(raw, combat);
            } else {
                if (encodedType != 2 || raw < 0 || raw >= 128) {
                    return false;
                }
                int base = (raw * 12) + MainActivity.STRUCT_OFFSET;
                int meta = MainActivity.this.renderWords[base];
                if ((Integer.MIN_VALUE & meta) == 0) {
                    return false;
                }
                int count = Math.min(9, (meta >>> 16) & 255);
                float sumX = 0.0f;
                float sumY = 0.0f;
                int used = 0;
                for (int j = 0; j < count; j++) {
                    int packed = MainActivity.this.renderWords[base + 3 + j] & 65535;
                    if (packed != 65535) {
                        sumX += (packed & 63) + 0.5f;
                        sumY += ((packed >>> 6) & 63) + 0.5f;
                        used++;
                    }
                }
                int packed2 = MainActivity.this.renderWords[base + 1] & 65535;
                float worldX2 = used > 0 ? sumX / used : (packed2 & 63) + 0.5f;
                worldY = used > 0 ? sumY / used : 0.5f + ((packed2 >>> 6) & 63);
                worldX = worldX2;
            }
            if (MainActivity.this.achievementMissionState.active) {
                MainActivity.this.achievementMissionState.fastCameraUsed = SMOOTH_HUD_PURCHASE_SCROLL;
            }
            beginFavoriteCameraMotion(worldX, worldY, null);
            invalidate();
            return SMOOTH_HUD_PURCHASE_SCROLL;
        }

        private boolean handleHudAttackTargetPortraitTap(float sx, float sy) {
            if (this.hudAttackTargetPortraitRect.isEmpty() || !this.hudAttackTargetPortraitRect.contains(sx, sy) || MainActivity.this.tacticalAux == null || MainActivity.this.tacticalAux.length < 14 || MainActivity.this.tacticalAux[0] != MainActivity.TACTICAL_AUX_MAGIC) {
                return false;
            }
            centerCameraOnEncodedObject(MainActivity.this.tacticalAux[13] & 65535);
            return SMOOTH_HUD_PURCHASE_SCROLL;
        }

