            this.hudMenuVisualItems = Math.max(0.0f, Math.min(max, this.hudMenuVisualItems));
            int columns = hudMenuColumns();
            this.hudMenuDrawStart = ((int) (this.hudMenuVisualItems / columns)) * columns;
            this.hudMenuDrawShiftY = ((this.hudMenuVisualItems - this.hudMenuDrawStart) / columns) * 30.0f;
