        private int packedAtScreen(float sx, float sy) {
            if (MainActivity.this.renderWords == null || !this.activeViewportRect.contains(sx, sy)) {
                return -1;
            }
            int bounds = MainActivity.this.renderWords[4];
            int minX = bounds & 255;
            int minY = (bounds >>> 8) & 255;
            int mapW = (bounds >>> 16) & 255;
            int mapH = (bounds >>> 24) & 255;
            float logicalX = this.cameraX + ((sx - this.viewportRect.left) / Math.max(1, this.currentScale));
            float logicalY = this.cameraY + ((sy - this.viewportRect.top) / Math.max(1, this.currentScale));
            int mx = (int) Math.floor(logicalX / MainActivity.TACTICAL_CURSOR_SPEED_CELLS_PER_SECOND);
            int my = (int) Math.floor(logicalY / MainActivity.TACTICAL_CURSOR_SPEED_CELLS_PER_SECOND);
            if (mx < 0 || my < 0 || mx >= mapW || my >= mapH) {
                return -1;
            }
            int x = minX + mx;
            int y = minY + my;
            return (y << 6) | x;
        }

        private int inspectedPackedForHud() {
            if (MainActivity.this.renderWords == null) {
                return -1;
            }
            int bounds = MainActivity.this.renderWords[4];
            int minX = bounds & 255;
            int minY = (bounds >>> 8) & 255;
            int mapW = (bounds >>> 16) & 255;
            int mapH = (bounds >>> 24) & 255;
            if (mapW <= 0 || mapH <= 0) {
                return -1;
            }
            int packed = this.inspectedMapPacked;
            int x = packed & 63;
            int y = (packed >>> 6) & 63;
            if (packed >= 0 && packed < 4096 && x >= minX && x < minX + mapW && y >= minY && y < minY + mapH) {
                return packed;
            }
            int packed2 = (MainActivity.this.renderWords[7] >>> 16) & 65535;
            int x2 = packed2 & 63;
            int y2 = (packed2 >>> 6) & 63;
            if (x2 >= minX && x2 < minX + mapW && y2 >= minY && y2 < minY + mapH) {
                return packed2;
            }
            int mx = Math.max(0, Math.min(mapW - 1, (int) Math.floor((this.cameraX + (this.currentActiveViewportLogicalW * 0.5f)) / MainActivity.TACTICAL_CURSOR_SPEED_CELLS_PER_SECOND)));
            int my = Math.max(0, Math.min(mapH - 1, (int) Math.floor((this.cameraY + (this.currentViewportLogicalH * 0.5f)) / MainActivity.TACTICAL_CURSOR_SPEED_CELLS_PER_SECOND)));
            return ((minY + my) << 6) | (minX + mx);
        }

        private String inspectedMapLabel() {
            int packed = inspectedPackedForHud();
            if (packed < 0 || MainActivity.this.renderWords == null) {
                return MainActivity.this.uiText("UNKNOWN", "НЕИЗВЕСТНО");
            }
            if (!isPackedUnveiled(packed)) {
                return MainActivity.this.uiText("UNEXPLORED", "НЕ РАЗВЕДАНО");
            }
            String object = visibleObjectNameAtPacked(packed);
            if (object != null && !object.isEmpty()) {
                return object;
            }
            int landscape = MainActivity.this.renderWords[packed + 16] & 15;
            switch (landscape) {
                case 0:
                    return MainActivity.this.uiText("SAND", "ПЕСОК");
                case 1:
                case 4:
                case 5:
                    return MainActivity.this.uiText("ROCK", "КАМЕНЬ");
                case 2:
                case 3:
                    return MainActivity.this.uiText("DUNES", "ДЮНЫ");
                case 6:
                case 7:
                    return MainActivity.this.uiText("MOUNTAIN", "ГОРЫ");
                case 8:
                    return MainActivity.this.uiText("SPICE", "СПАЙС");
                case 9:
                    return MainActivity.this.uiText("THICK SPICE", "ГУСТОЙ СПАЙС");
                case 10:
                    return MainActivity.this.uiText("CONCRETE", "БЕТОН");
                case 11:
                    return MainActivity.this.uiText("WALL", "СТЕНА");
                case 12:
                    return MainActivity.this.uiText("STRUCTURE", "ЗДАНИЕ");
                case 13:
                    return MainActivity.this.uiText("DESTROYED WALL", "РУИНЫ СТЕНЫ");
                case 14:
                    return MainActivity.this.uiText("SPICE BLOOM", "СПАЙС-БЛУМ");
                default:
                    return MainActivity.this.uiText("TERRAIN ", "МЕСТНОСТЬ ") + landscape;
            }
        }

        private String visibleObjectNameAtPacked(int packed) {
            int type;
            if (MainActivity.this.renderWords == null || packed < 0 || packed >= 4096) {
                return null;
            }
            int i = 0;
            while (true) {
                boolean parkedHarvester = false;
                if (i < 128) {
                    int base = (i * 4) + MainActivity.UNIT_OFFSET;
                    int meta = MainActivity.this.renderWords[base];
                    if ((Integer.MIN_VALUE & meta) != 0 && ((type = (meta >>> 8) & 255) < 18 || type > 24)) {
                        int aux = (MainActivity.this.unitRenderAux == null || i >= MainActivity.this.unitRenderAux.length) ? 0 : MainActivity.this.unitRenderAux[i];
                        int combat = (MainActivity.this.unitCombatAux == null || i >= MainActivity.this.unitCombatAux.length) ? 0 : MainActivity.this.unitCombatAux[i];
                        if (type == 16 && (536870912 & combat) != 0) {
                            parkedHarvester = true;
                        }
                        if (((16777216 & aux) == 0 || parkedHarvester) && isUnitVisibleToPlayer(meta, base) && (65535 & MainActivity.this.renderWords[base + 2]) == packed) {
                            return unitShortName(type);
                        }
                    }
                    i++;
                } else {
                    int playerHouse = MainActivity.this.renderWords[5] & 255;
                    int i2 = 0;
                    while (i2 < 128) {
                        int base2 = (i2 * 12) + MainActivity.STRUCT_OFFSET;
                        int meta2 = MainActivity.this.renderWords[base2];
                        if ((meta2 & Integer.MIN_VALUE) != 0) {
                            int visibilityWord = (MainActivity.this.structureRenderAux == null || i2 >= MainActivity.this.structureRenderAux.length) ? 0 : MainActivity.this.structureRenderAux[i2];
                            int seenMask = visibilityWord & 63;
                            if (MainActivity.this.cheatRevealMap || playerHouse >= 6 || ((1 << playerHouse) & seenMask) != 0) {
                                int count = (meta2 >>> 16) & 255;
                                for (int j = 0; j < count && j < 9; j++) {
                                    if ((MainActivity.this.renderWords[base2 + 3 + j] & 65535) == packed) {
                                        return structureShortName((meta2 >>> 8) & 255);
                                    }
                                }
                            }
                        }
                        i2++;
                    }
                    return null;
                }
            }
        }

        private void refreshConstructionPreviewValidation() {
            if (MainActivity.this.nativeHandle == 0 || selectedConstructionPhase() != 2 || this.constructionPreviewPacked < 0) {
                return;
            }
            int validation = MainActivity.nativeConstructionValidatePacked(MainActivity.this.nativeHandle, this.constructionPreviewPacked);
            this.constructionPreviewValidation = validation;
            int i = MainActivity.CONSTRUCTION_PREVIEW_UNAVAILABLE;
            if (validation != MainActivity.CONSTRUCTION_PREVIEW_UNAVAILABLE) {
                i = MainActivity.nativeConstructionPreviewCellMaskPacked(MainActivity.this.nativeHandle, this.constructionPreviewPacked);
            }
            this.constructionPreviewCellMask = i;
        }

        private void updateConstructionPreviewAtScreen(float sx, float sy) {
            if (MainActivity.this.nativeHandle == 0 || selectedConstructionPhase() != 2) {
                clearConstructionPreview();
                return;
            }
            int packed = packedAtScreen(sx, sy);
            if (packed < 0) {
                return;
            }
            this.constructionPreviewPacked = packed;
            refreshConstructionPreviewValidation();
            int validation = this.constructionPreviewValidation;
            if (validation == MainActivity.CONSTRUCTION_PREVIEW_UNAVAILABLE) {
                this.constructionFeedback = "PREVIEW UNAVAILABLE";
                return;
            }
            if (validation == 0) {
                this.constructionFeedback = "INVALID PLACE";
            } else if (validation < 0) {
                this.constructionFeedback = "POOR FOUNDATION • TAP AGAIN";
            } else {
                this.constructionFeedback = "VALID • TAP AGAIN";
            }
        }

