        private void handleRadarTap(float sx, float sy) {
            if (MainActivity.this.renderWords == null || this.radarRect.width() <= 0.0f || this.radarRect.height() <= 0.0f) {
                return;
            }
            int bounds = MainActivity.this.renderWords[4];
            int minX = bounds & 255;
            int minY = (bounds >>> 8) & 255;
            int mapW = (bounds >>> 16) & 255;
            int mapH = (bounds >>> 24) & 255;
            if (mapW <= 0 || mapH <= 0) {
                return;
            }
            if (MainActivity.this.achievementMissionState.active) {
                MainActivity.this.achievementMissionState.fastCameraUsed = SMOOTH_HUD_PURCHASE_SCROLL;
            }
            float nx = Math.max(0.0f, Math.min(0.999999f, (sx - this.radarRect.left) / Math.max(1.0f, this.radarRect.width())));
            float ny = Math.max(0.0f, Math.min(0.999999f, (sy - this.radarRect.top) / Math.max(1.0f, this.radarRect.height())));
            int localX = Math.max(0, Math.min(mapW - 1, (int) Math.floor(mapW * nx)));
            int localY = Math.max(0, Math.min(mapH - 1, (int) Math.floor(mapH * ny)));
            beginFavoriteCameraMotion(minX + localX + 0.5f, minY + localY + 0.5f, null);
        }

