        private void drawTerrain(Canvas canvas, int minX, int minY, int mapW, int mapH, Layout layout) {
            int lastY;
            int firstY;
            int lastX;
            Bitmap overlayTile;
            Layout layout2 = layout;
            if (MainActivity.this.terrainArt == null) {
                return;
            }
            int firstX = Math.max(0, ((int) Math.floor(this.cameraX / MainActivity.TACTICAL_CURSOR_SPEED_CELLS_PER_SECOND)) - 1);
            int firstY2 = Math.max(0, ((int) Math.floor(this.cameraY / MainActivity.TACTICAL_CURSOR_SPEED_CELLS_PER_SECOND)) - 1);
            int lastX2 = Math.min(mapW, ((int) Math.ceil((this.cameraX + this.currentViewportLogicalW) / MainActivity.TACTICAL_CURSOR_SPEED_CELLS_PER_SECOND)) + 1);
            int lastY2 = Math.min(mapH, ((int) Math.ceil((this.cameraY + this.currentViewportLogicalH) / MainActivity.TACTICAL_CURSOR_SPEED_CELLS_PER_SECOND)) + 1);
            float tileSize = layout2.scale * 32;
            int my = firstY2;
            while (my < lastY2) {
                int y = minY + my;
                int mx = firstX;
                while (mx < lastX2) {
                    int x = minX + mx;
                    int packed = (y << 6) | x;
                    int word = MainActivity.this.renderWords[packed + 16];
                    int firstX2 = firstX;
                    Bitmap terrainTile = getTerrainBitmap(word);
                    if (terrainTile == null) {
                        lastY = lastY2;
                        firstY = firstY2;
                        lastX = lastX2;
                    } else {
                        lastY = lastY2;
                        float l = layout2.viewLeft + (layout2.scale * ((mx * 32) - this.cameraX));
                        firstY = firstY2;
                        float t = layout2.viewTop + (layout2.scale * ((my * 32) - this.cameraY));
                        lastX = lastX2;
                        this.tileRect.set(l, t, l + tileSize, t + tileSize);
                        canvas.drawBitmap(terrainTile, (Rect) null, this.tileRect, this.bitmapPaint);
                        int impactOverlay = (word >>> 4) & 15;
                        if (impactOverlay != 0 && (overlayTile = MainActivity.this.terrainArt.getImpactOverlay(impactOverlay)) != null) {
                            canvas.drawBitmap(overlayTile, (Rect) null, this.tileRect, this.bitmapPaint);
                        }
                    }
                    mx++;
                    layout2 = layout;
                    firstX = firstX2;
                    lastY2 = lastY;
                    firstY2 = firstY;
                    lastX2 = lastX;
                }
                my++;
                layout2 = layout;
            }
        }

        private Bitmap getTerrainBitmap(int mapWord) {
            if (MainActivity.this.terrainArt == null) {
                return null;
            }
            int logicalTerrain = mapWord & 15;
            if (logicalTerrain == 10) {
                return MainActivity.this.terrainArt.getMetatile(MainActivity.TERRAIN_CONCRETE_METATILE);
            }
            if (logicalTerrain == 14) {
                return MainActivity.this.terrainArt.getMetatile(MainActivity.TERRAIN_SPICE_BLOOM_METATILE);
            }
            int baseTile = (mapWord >>> 8) & 255;
            return MainActivity.this.terrainArt.getMetatile(baseTile);
        }

        private void drawFogOverlay(Canvas canvas, int minX, int minY, int mapW, int mapH, Layout layout) {
            int y;
            WorldView worldView = this;
            if (MainActivity.this.terrainArt != null && !MainActivity.this.cheatRevealMap) {
                int firstX = Math.max(0, ((int) Math.floor(worldView.cameraX / MainActivity.TACTICAL_CURSOR_SPEED_CELLS_PER_SECOND)) - 1);
                int firstY = Math.max(0, ((int) Math.floor(worldView.cameraY / MainActivity.TACTICAL_CURSOR_SPEED_CELLS_PER_SECOND)) - 1);
                int i = mapW;
                int lastX = Math.min(i, ((int) Math.ceil((worldView.cameraX + worldView.currentViewportLogicalW) / MainActivity.TACTICAL_CURSOR_SPEED_CELLS_PER_SECOND)) + 1);
                int i2 = mapH;
                int lastY = Math.min(i2, ((int) Math.ceil((worldView.cameraY + worldView.currentViewportLogicalH) / MainActivity.TACTICAL_CURSOR_SPEED_CELLS_PER_SECOND)) + 1);
                float tileSize = layout.scale * 32;
                int my = firstY;
                while (my < lastY) {
                    int y2 = minY + my;
                    int mx = firstX;
                    while (mx < lastX) {
                        int x = minX + mx;
                        int mask = worldView.fogMaskForTile(x, y2, minX, minY, i, i2);
                        if (mask == 0) {
                            y = y2;
                        } else {
                            Bitmap fog = MainActivity.this.terrainArt.getFogOverlay(mask);
                            if (fog == null) {
                                y = y2;
                            } else {
                                float l = layout.viewLeft + (((mx * 32) - worldView.cameraX) * layout.scale);
                                float t = layout.viewTop + (((my * 32) - worldView.cameraY) * layout.scale);
                                y = y2;
                                worldView.tileRect.set(l, t, l + tileSize, t + tileSize);
                                canvas.drawBitmap(fog, (Rect) null, worldView.tileRect, worldView.bitmapPaint);
                            }
                        }
                        mx++;
                        worldView = this;
                        i = mapW;
                        i2 = mapH;
                        y2 = y;
                    }
                    my++;
                    worldView = this;
                    i = mapW;
                    i2 = mapH;
                }
            }
        }

        private int fogMaskForTile(int x, int y, int minX, int minY, int mapW, int mapH) {
            if (!isFogMapTileUnveiled(x, y)) {
                return 15;
            }
            int mask = isFogMapTileUnveiled(x, y + (-1)) ? 0 : 0 | 1;
            if (!isFogMapTileUnveiled(x + 1, y)) {
                mask |= 2;
            }
            if (!isFogMapTileUnveiled(x, y + 1)) {
                mask |= 4;
            }
            return !isFogMapTileUnveiled(x + (-1), y) ? mask | 8 : mask;
        }

        private boolean isFogMapTileUnveiled(int x, int y) {
            if (x < 0 || x >= 64 || y < 0 || y >= 64) {
                return false;
            }
            if (MainActivity.this.cheatRevealMap) {
                return SMOOTH_HUD_PURCHASE_SCROLL;
            }
            int packed = (y << 6) | x;
            if (((MainActivity.this.renderWords[packed + 16] >>> 24) & 1) != 0) {
                return SMOOTH_HUD_PURCHASE_SCROLL;
            }
            return false;
        }

        private boolean isUnveiled(int x, int y, int minX, int minY, int mapW, int mapH) {
            if (x < minX || x >= minX + mapW || y < minY || y >= minY + mapH) {
                return false;
            }
            if (MainActivity.this.cheatRevealMap) {
                return SMOOTH_HUD_PURCHASE_SCROLL;
            }
            int packed = (y << 6) | x;
            if (((MainActivity.this.renderWords[packed + 16] >>> 24) & 1) != 0) {
                return SMOOTH_HUD_PURCHASE_SCROLL;
            }
            return false;
        }

