        private void drawHudCursorPortrait(Canvas canvas, float left, float top, float size) {
            float inset = Math.max(1.0f, 0.045f * size);
            float l = left + inset;
            float t = top + inset;
            float r = (left + size) - inset;
            float b = (top + size) - inset;
            float c = size * 0.34f;
            this.linePaint.setStyle(Paint.Style.STROKE);
            this.linePaint.setStrokeCap(Paint.Cap.SQUARE);
            this.linePaint.setColor(Color.rgb(245, 225, 135));
            this.linePaint.setStrokeWidth(Math.max(1.0f, this.density * 0.8f));
            canvas.drawLine(l, t, l + c, t, this.linePaint);
            canvas.drawLine(l, t, l, t + c, this.linePaint);
            canvas.drawLine(r, t, r - c, t, this.linePaint);
            canvas.drawLine(r, t, r, t + c, this.linePaint);
            canvas.drawLine(l, b, l + c, b, this.linePaint);
            canvas.drawLine(l, b, l, b - c, this.linePaint);
            canvas.drawLine(r, b, r - c, b, this.linePaint);
            canvas.drawLine(r, b, r, b - c, this.linePaint);
            this.linePaint.setStrokeCap(Paint.Cap.BUTT);
        }

