        private Bitmap getStructurePortrait(int type) {
            if (type < 0 || type >= MainActivity.STRUCTURE_NAMES.length || MainActivity.this.terrainArt == null) {
                return null;
            }
            Bitmap cached = this.structurePortraitCache.get(Integer.valueOf(type));
            if (cached != null) {
                return cached;
            }
            int minDx = 4;
            int minDy = 4;
            int maxDx = -1;
            int maxDy = -1;
            for (int dy = 0; dy < 3; dy++) {
                for (int dx = 0; dx < 3; dx++) {
                    if (getStructureCellBitmap(type, 0, (dy << 6) | dx) != null) {
                        if (dx < minDx) {
                            minDx = dx;
                        }
                        if (dy < minDy) {
                            minDy = dy;
                        }
                        if (dx > maxDx) {
                            maxDx = dx;
                        }
                        if (dy > maxDy) {
                            maxDy = dy;
                        }
                    }
                }
            }
            if (maxDx < minDx || maxDy < minDy) {
                return null;
            }
            Bitmap portrait = Bitmap.createBitmap(((maxDx - minDx) + 1) * 32, ((maxDy - minDy) + 1) * 32, Bitmap.Config.ARGB_8888);
            Canvas c = new Canvas(portrait);
            for (int dy2 = minDy; dy2 <= maxDy; dy2++) {
                for (int dx2 = minDx; dx2 <= maxDx; dx2++) {
                    Bitmap tile = getStructureCellBitmap(type, 0, (dy2 << 6) | dx2);
                    if (tile != null) {
                        c.drawBitmap(tile, (dx2 - minDx) * 32, (dy2 - minDy) * 32, (Paint) null);
                    }
                }
            }
            this.structurePortraitCache.put(Integer.valueOf(type), portrait);
            return portrait;
        }

