        private void drawFrontScenarioMissionLabel(Canvas canvas, int house, int mission, RectF labelRect, boolean enabled, boolean currentUnlocked, float genesisScale) {
            Bitmap label = this.frontScenarioLabelCache[house][mission - 1];
            if (label == null && MainActivity.this.mentatRenderer != null) {
                String text = MainActivity.this.russianLocalizationUiActive() ? "MlCClr " + mission : MainActivity.this.uiText("MISSION ", "МИССИЯ ") + mission;
                label = MainActivity.this.mentatRenderer.renderUiLabel(house, mission, text);
                this.frontScenarioLabelCache[house][mission - 1] = label;
            }
            if (label == null) {
                return;
            }
            float scale = Math.max(0.1f, genesisScale);
            float w = label.getWidth() * scale;
            float h = label.getHeight() * scale;
            RectF dst = new RectF(labelRect.centerX() - (w * 0.5f), labelRect.centerY() - (h * 0.5f), labelRect.centerX() + (w * 0.5f), labelRect.centerY() + (0.5f * h));
            int oldAlpha = this.bitmapPaint.getAlpha();
            boolean oldFilter = this.bitmapPaint.isFilterBitmap();
            this.bitmapPaint.setFilterBitmap(false);
            this.bitmapPaint.setAlpha(currentUnlocked ? 255 : enabled ? 235 : 112);
            canvas.drawBitmap(label, (Rect) null, dst, this.bitmapPaint);
            this.bitmapPaint.setAlpha(oldAlpha);
            this.bitmapPaint.setFilterBitmap(oldFilter);
        }

        private void ensureFrontScenarioPreviews(int house, int unlocked, boolean campaignComplete) {
            if (house < 0 || house >= this.frontScenarioPreviewCache.length || MainActivity.this.runtimeWorldDataPack == null || MainActivity.this.runtimeGameplayDataPack == null || MainActivity.this.runtimeNativeDataPack == null) {
                return;
            }
            int lastPreviewMission = campaignComplete ? Math.min(9, unlocked) : Math.max(0, unlocked - 1);
            int preparedThrough = Math.max(0, Math.min(9, this.frontScenarioPreviewPreparedThrough[house]));
            if (preparedThrough >= lastPreviewMission) {
                return;
            }
            for (int mission = preparedThrough + 1; mission <= lastPreviewMission; mission++) {
                this.frontScenarioPreviewCache[house][mission - 1] = buildFrontScenarioPreview(house, mission);
            }
            this.frontScenarioPreviewPreparedThrough[house] = lastPreviewMission;
            postInvalidateOnAnimation();
        }

        private Bitmap buildFrontScenarioPreview(int house, int mission) {
            String asset = MainActivity.scenarioAssetForHouseMission(house, mission);
            int campaignId = CampaignLevelFlow.campaignIdForLevel(mission);
            long handle = MainActivity.nativeCreateRecovered(MainActivity.this.runtimeWorldDataPack, MainActivity.this.runtimeGameplayDataPack, MainActivity.this.runtimeNativeDataPack, asset, campaignId);
            if (handle == 0) {
                return null;
            }
            try {
                int wordCount = MainActivity.nativeRenderWordCount();
                if (wordCount <= 0) {
                    return null;
                }
                int[] words = new int[wordCount];
                if (MainActivity.nativeFillRenderSnapshot(handle, words)) {
                    return renderFrontScenarioPreview(words);
                }
                return null;
            } finally {
                MainActivity.nativeDestroy(handle);
            }
        }

