        private void plotPreviewPacked(int[] pixels, int size, int ox, int oy, int cell, int minX, int minY, int mapW, int mapH, int packed, int color, int drawSize) {
            int px = packed & 63;
            int py = (packed >>> 6) & 63;
            int localX = px - minX;
            int localY = py - minY;
            if (localX >= 0 && localY >= 0) {
                if (localX < mapW) {
                    if (localY >= mapH) {
                        return;
                    }
                    int sx = ox + (localX * cell) + Math.max(0, (cell - drawSize) / 2);
                    int sy = oy + (localY * cell) + Math.max(0, (cell - drawSize) / 2);
                    fillPreviewCell(pixels, size, sx, sy, Math.max(1, drawSize), color);
                }
            }
        }

        private void fillPreviewCell(int[] pixels, int size, int sx, int sy, int cell, int color) {
            for (int yy = 0; yy < cell; yy++) {
                int py = sy + yy;
                if (py >= 0 && py < size) {
                    int row = py * size;
                    for (int xx = 0; xx < cell; xx++) {
                        int px = sx + xx;
                        if (px >= 0 && px < size) {
                            pixels[row + px] = color;
                        }
                    }
                }
            }
        }

        private int previewTerrainColor(int landscape) {
            switch (landscape) {
                case 1:
                case 4:
                case 5:
                case 10:
                    return Color.rgb(92, 100, RazorSpriteSatObjectCallSiteTrace.SOURCE_BYTE_OFFSET);
                case 2:
                case 3:
                    return Color.rgb(152, 118, 68);
                case 6:
                case 7:
                case 11:
                case 12:
                case 13:
                    return Color.rgb(64, 72, 79);
                case 8:
                    return Color.rgb(173, DuneHackR82cRazorCombatAudit.DAMAGE_WORDS, 45);
                case 9:
                case 14:
                    return Color.rgb(219, 174, 58);
                default:
                    return Color.rgb(118, 96, 58);
            }
        }

