        private void drawSaveListScrollIndicator(Canvas canvas, float u, float top, float height) {
            float maxScroll = loadScrollMax(u);
            float fraction = 0.0f;
            if (maxScroll <= 0.0f) {
                return;
            }
            float trackLeft = this.debugPanelRect.right - (9.0f * u);
            float trackRight = this.debugPanelRect.right - (6.0f * u);
            float trackTop = top + (u * 1.0f);
            float trackBottom = (top + height) - (u * 1.0f);
            this.panelPaint.setStyle(Paint.Style.FILL);
            this.panelPaint.setColor(Color.argb(GenesisMissionSequenceArt.PANEL_HEIGHT, MainActivity.MENU_ACTION_SETTINGS_FRIENDLY_TARGETS, 48, 51));
            canvas.drawRoundRect(trackLeft, trackTop, trackRight, trackBottom, u * 1.5f, u * 1.5f, this.panelPaint);
            float viewportHeight = Math.max(1.0f, height);
            float contentHeight = viewportHeight + maxScroll;
            float thumbH = Math.max(18.0f * u, ((trackBottom - trackTop) * viewportHeight) / contentHeight);
            float travel = Math.max(0.0f, (trackBottom - trackTop) - thumbH);
            if (maxScroll > 0.0f) {
                fraction = this.menuLoadScrollOffset / maxScroll;
            }
            float thumbTop = trackTop + (travel * fraction);
            this.panelPaint.setColor(Color.rgb(GenesisCampaignTransitionRenderer.INITIAL_MAP_HOLD_TICKS, 137, 154));
            canvas.drawRoundRect(trackLeft, thumbTop, trackRight, thumbTop + thumbH, u * 1.5f, u * 1.5f, this.panelPaint);
        }

