            RectF fpsToggle = this.menuItemRects[2];
            fpsToggle.set(x, fpsTop, this.debugPanelRect.right - (u * 14.0f), fpsTop + toggleH);
            drawDiagnosticCheckbox(canvas, fpsToggle, MainActivity.this.uiText("SHOW FPS", "ПОКАЗЫВАТЬ FPS"), MainActivity.this.showFpsEnabled, u);
            RectF report = this.menuItemRects[0];
