        private void drawDiagnosticCheckbox(Canvas canvas, RectF row, String label, boolean checked, float u) {
            float box = 11.0f * u;
            float boxLeft = row.left + (2.0f * u);
            float boxTop = row.centerY() - (0.5f * box);
            this.linePaint.setStyle(Paint.Style.STROKE);
            this.linePaint.setStrokeWidth(Math.max(1.0f, u));
            this.linePaint.setColor(checked ? Color.rgb(188, 158, 93) : Color.rgb(102, RazorSpriteSatObjectCallSiteTrace.SOURCE_BYTE_OFFSET, RazorSpriteSatObjectCallSiteTrace.SOURCE_BYTE_OFFSET));
            canvas.drawRect(boxLeft, boxTop, boxLeft + box, boxTop + box, this.linePaint);
            if (checked) {
                this.linePaint.setStrokeWidth(Math.max(1.4f, 1.5f * u));
                this.linePaint.setColor(Color.rgb(229, 226, 214));
                canvas.drawLine(boxLeft + (2.2f * u), boxTop + (5.5f * u), boxLeft + (u * 4.6f), boxTop + (u * 8.2f), this.linePaint);
                canvas.drawLine(boxLeft + (4.6f * u), boxTop + (u * 8.2f), boxLeft + (9.2f * u), boxTop + (2.4f * u), this.linePaint);
            }
            this.textPaint.setTextAlign(Paint.Align.LEFT);
            this.textPaint.setFakeBoldText(false);
            this.textPaint.setTextSize(8.0f * u);
            this.textPaint.setColor(Color.rgb(198, 202, 201));
            canvas.drawText(label, boxLeft + box + (7.0f * u), row.centerY() + (2.8f * u), this.textPaint);
        }

        private float debugSection(Canvas canvas, float x, float y, String title) {
            float y2 = y + (this.debugTextScale * 8.0f);
            this.textPaint.setTextSize(this.debugTextScale * 9.0f);
            this.textPaint.setFakeBoldText(SMOOTH_HUD_PURCHASE_SCROLL);
            this.textPaint.setColor(Color.rgb(211, 181, 110));
            canvas.drawText(title, x, y2, this.textPaint);
            this.textPaint.setFakeBoldText(false);
            float lineStart = this.textPaint.measureText(title) + x + (this.debugTextScale * 8.0f);
            this.linePaint.setStyle(Paint.Style.STROKE);
            this.linePaint.setStrokeWidth(Math.max(1.0f, this.debugTextScale * 0.75f));
            this.linePaint.setColor(Color.rgb(66, 65, MainActivity.RADAR_DISABLE_FINAL_TICKS));
            canvas.drawLine(lineStart, y2 - (this.debugTextScale * 3.0f), this.debugPanelRect.right - (this.debugTextScale * 14.0f), y2 - (this.debugTextScale * 3.0f), this.linePaint);
            return (this.debugTextScale * 11.0f) + y2;
        }

        private float debugLine(Canvas canvas, float x, float y, float line, String label, String value) {
            this.textPaint.setTextSize(this.debugTextScale * 10.0f);
            this.textPaint.setColor(Color.rgb(145, 145, 145));
            canvas.drawText(label + ":", x, y, this.textPaint);
            float valueX = Math.max(this.debugTextScale * MainActivity.TACTICAL_CURSOR_FAST_MAX_CELLS_PER_SECOND, this.textPaint.measureText(label + ":  ")) + x;
            this.textPaint.setColor(Color.rgb(225, 225, 225));
            float maxWidth = (this.debugPanelRect.right - valueX) - (this.debugTextScale * 14.0f);
            canvas.drawText(ellipsizeDebugValue(value, maxWidth), valueX, y, this.textPaint);
            return y + line;
        }

        private String ellipsizeDebugValue(String value, float maxWidth) {
            if (maxWidth <= 0.0f || this.textPaint.measureText(value) <= maxWidth) {
                return value;
            }
            float suffixWidth = this.textPaint.measureText("...");
            int count = this.textPaint.breakText(value, SMOOTH_HUD_PURCHASE_SCROLL, Math.max(0.0f, maxWidth - suffixWidth), null);
            return value.substring(0, Math.max(0, count)) + "...";
        }

        private String packedCoordinates(int packed) {
            return (packed & 63) + "," + ((packed >>> 6) & 63);
        }

        private String debugProductionState() {
            int pct;
            if (selectedConstructionPhase() >= 0 && MainActivity.this.constructionAux != null) {
                int phase = selectedConstructionPhase();
                int type = (MainActivity.this.constructionAux[1] >>> 24) & 255;
                if (phase == 1) {
                    int remain = MainActivity.this.constructionAux[3] & 65535;
                    int total = (MainActivity.this.constructionAux[3] >>> 16) & 65535;
                    pct = total > 0 ? Math.max(0, Math.min(100, (int) Math.round(((total - remain) * 100.0d) / total))) : 0;
                    return "BUILD " + structureName(type) + " " + pct + "%";
                }
                if (phase == 2) {
                    return "READY " + structureName(type);
                }
                if (phase == 4) {
                    return "CONSTRUCTION YARD UPGRADE";
                }
            }
            if (selectedFactoryPhase() >= 0 && MainActivity.this.factoryAux != null) {
                int phase2 = selectedFactoryPhase();
                int type2 = (MainActivity.this.factoryAux[1] >>> 24) & 255;
                if (phase2 == 1) {
                    int remain2 = MainActivity.this.factoryAux[3] & 65535;
                    int total2 = (MainActivity.this.factoryAux[3] >>> 16) & 65535;
                    pct = total2 > 0 ? Math.max(0, Math.min(100, (int) Math.round(((total2 - remain2) * 100.0d) / total2))) : 0;
                    return "PRODUCE " + unitName(type2) + " " + pct + "%";
                }
                if (phase2 == 2) {
                    return "READY " + unitName(type2);
                }
                if (phase2 == 4) {
                    return structureName(selectedFactoryStructureType()) + " UPGRADE";
                }
            }
            return this.constructionFeedback.isEmpty() ? "NONE" : this.constructionFeedback;
        }

        private String structureName(int type) {
            String base = MainActivity.this.russianHudObjectNames != null ? MainActivity.this.russianHudObjectNames.structure(type) : null;
            if (base == null && MainActivity.this.germanLocalizationUiActive()) {
                base = GermanHudNames.structure(type);
            }
            if (base == null) {
                base = (type < 0 || type >= MainActivity.STRUCTURE_NAMES.length) ? "T" + type : MainActivity.STRUCTURE_NAMES[type];
            }
            return MainActivity.this.objectNameCorrections.structure(type, base);
        }

